import './addFrnds.scss';
import { useContext, useEffect, useState } from 'react';
import { AuthContext } from '../../context/authContext';
import axios from 'axios';
import { Link } from 'react-router-dom';

const AddFriends = () => {
  const { currentUser, token, loading: authLoading, error: authError } = useContext(AuthContext);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  console.log('AddFriends: currentUser=', currentUser);
  console.log('AddFriends: token=', token);
  console.log('AddFriends: authLoading=', authLoading);
  console.log('AddFriends: authError=', authError);

  useEffect(() => {
    const fetchUsers = async () => {
      if (authLoading) {
        console.log('AddFriends: Waiting for AuthContext to load');
        return;
      }

      if (!currentUser || !token) {
        console.log('AddFriends: No currentUser or token, cannot fetch users');
        setError('Please log in to add friends.');
        setLoading(false);
        return;
      }

      try {
        console.log('AddFriends: Sending GET request to http://localhost:5000/api/users/all');
        const res = await axios.get('http://localhost:5000/api/users/all', {
          headers: { Authorization: `Bearer ${token}` },
        });
        console.log('AddFriends: Fetch users response=', {
          status: res.status,
          data: JSON.stringify(res.data, null, 2),
        });

        // Fetch current user's friends to filter them out
        console.log('AddFriends: Sending GET request to http://localhost:5000/api/users/me');
        const userRes = await axios.get('http://localhost:5000/api/users/me', {
          headers: { Authorization: `Bearer ${token}` },
        });
        console.log('AddFriends: Fetch current user response=', {
          status: userRes.status,
          data: JSON.stringify(userRes.data, null, 2),
        });

        const friendIds = userRes.data.friends?.map((friend) => friend._id) || [];
        const nonFriends = res.data.filter((user) => !friendIds.includes(user._id) && user._id !== currentUser._id);
        console.log('AddFriends: Setting non-friends=', nonFriends);
        setUsers(nonFriends);
        setError(null);
      } catch (err) {
        console.error('AddFriends: Error fetching users:', err.message);
        console.error('AddFriends: Error details:', {
          status: err.response?.status,
          data: JSON.stringify(err.response?.data, null, 2),
        });
        const errorMessage = err.response?.status === 401
          ? 'Session expired. Please log in again.'
          : err.response?.data?.message || 'Failed to load users.';
        setError(errorMessage);
        setUsers([]);
      } finally {
        setLoading(false);
        console.log('AddFriends: fetchUsers completed, loading=', false);
      }
    };

    fetchUsers();
  }, [currentUser, token, authLoading]);

  const sendFriendRequest = async (userId) => {
    try {
      console.log(`AddFriends: Sending friend request to user ID: ${userId}`);
      const res = await axios.post(
        `http://localhost:5000/api/users/${userId}/friend-request`,
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );
      console.log('AddFriends: Friend request response=', {
        status: res.status,
        data: JSON.stringify(res.data, null, 2),
      });
      alert('Friend request sent successfully!');
      // Optionally, remove the user from the list
      setUsers(users.filter((user) => user._id !== userId));
    } catch (err) {
      console.error('AddFriends: Error sending friend request:', err.message);
      console.error('AddFriends: Error details:', {
        status: err.response?.status,
        data: JSON.stringify(err.response?.data, null, 2),
      });
      const errorMessage = err.response?.data?.message || 'Failed to send friend request.';
      alert(errorMessage);
    }
  };

  if (authLoading || loading) {
    return <div className="add-friends">Loading users...</div>;
  }

  if (error) {
    return (
      <div className="add-friends error">
        <p>{error}</p>
        <button onClick={() => window.location.reload()}>Retry</button>
      </div>
    );
  }

  return (
    <div className="add-friends">
      <h2>Add Friends</h2>
      {users.length === 0 ? (
        <p>No users available to add as friends.</p>
      ) : (
        <div className="users-list">
          {users.map((user) => (
            <div key={user._id} className="user-card">
              <Link to={`/profile/${user._id}`}>
                <img
                  src={user.profilePicture || '/default-avatar.png'}
                  alt={`${user.username}'s profile`}
                  className="avatar"
                  onError={(e) => {
                    console.error(`AddFriends: Image load error for ${user.username}:`, e);
                    e.target.src = '/default-avatar.png';
                  }}
                />
                <div className="info">
                  <h3>{user.username}</h3>
                  <p>{user.name}</p>
                </div>
              </Link>
              <button onClick={() => sendFriendRequest(user._id)}>
                Send Friend Request
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default AddFrnds;
